const fs = require("node:fs");
const path = require("node:path");
const {
  withAndroidManifest,
  withDangerousMod,
  withMainActivity,
  withMainApplication,
  withStringsXml,
  AndroidConfig,
} = require("expo/config-plugins");

// Daseo delta 64: Daseo as an Android digital assistant, so holding the Galaxy side button opens
// a new agent through `paseo://quick-ask`. `android/` is generated by prebuild, so the Kotlin
// sources live here as templates and the manifest, MainActivity and MainApplication are patched
// on every prebuild.
const TEMPLATE_DIR = path.join(__dirname, "android-assistant-entry");
const KOTLIN_TEMPLATES = ["DaseoQuickAsk.kt.template", "DaseoAssistantServices.kt.template"];
const ASSISTANT_PROCESS = ":assistant";
const ALIAS_NAME = ".DaseoAssistActivity";
const TRAMPOLINE_NAME = ".DaseoQuickAskTrampolineActivity";
const VOICE_INTERACTION_XML = "daseo_voice_interaction_service";
const RECOGNITION_SERVICE_XML = "daseo_recognition_service";
const SHORTCUTS_XML = "daseo_shortcuts";
const QUICK_ASK_URL = "paseo://quick-ask";
const QUICK_ASK_LABELS = {
  values: "Quick ask",
  "values-ko": "빠른 질문",
};

const ACTIVITY_CREATE_LINE = "    super.onCreate(null)";
const ACTIVITY_TRACK_LINE = "    DaseoQuickAsk.trackForeground(this)";
const ACTIVITY_PREPARE_LINE =
  "    DaseoQuickAsk.prepareLaunchIntent(intent, fromForeground = false)";
const ACTIVITY_COMPONENT_LINE = "  override fun getMainComponentName(): String";
const APPLICATION_CREATE_LINE = "    super.onCreate()";
const APPLICATION_GUARD_LINE = "    if (DaseoQuickAsk.isAssistantProcess()) return";

function buildVoiceInteractionXml(packageName) {
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<voice-interaction-service xmlns:android="http://schemas.android.com/apk/res/android"',
    `    android:sessionService="${packageName}.DaseoVoiceInteractionSessionService"`,
    `    android:recognitionService="${packageName}.DaseoRecognitionService"`,
    '    android:supportsAssist="true"',
    '    android:supportsLaunchVoiceAssistFromKeyguard="true"',
    '    android:supportsLocalInteraction="false" />',
    "",
  ].join("\n");
}

function buildRecognitionServiceXml() {
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<recognition-service xmlns:android="http://schemas.android.com/apk/res/android"',
    '    android:selectableAsDefault="false" />',
    "",
  ].join("\n");
}

function buildShortcutsXml(packageName) {
  return [
    '<?xml version="1.0" encoding="utf-8"?>',
    '<shortcuts xmlns:android="http://schemas.android.com/apk/res/android">',
    "  <shortcut",
    '      android:shortcutId="quick_ask"',
    '      android:enabled="true"',
    '      android:icon="@mipmap/ic_launcher"',
    '      android:shortcutShortLabel="@string/daseo_quick_ask"',
    '      android:shortcutLongLabel="@string/daseo_quick_ask">',
    "    <intent",
    '        android:action="android.intent.action.VIEW"',
    `        android:data="${QUICK_ASK_URL}"`,
    `        android:targetPackage="${packageName}"`,
    `        android:targetClass="${packageName}.MainActivity" />`,
    "  </shortcut>",
    "</shortcuts>",
    "",
  ].join("\n");
}

function upsertByName(list, entry) {
  const name = entry.$["android:name"];
  const next = (list ?? []).filter((item) => item.$?.["android:name"] !== name);
  next.push(entry);
  return next;
}

function addAssistantEntryToManifest(manifest) {
  const application = manifest.application?.[0];
  const mainActivity = application?.activity?.find(
    (activity) => activity.$["android:name"] === ".MainActivity",
  );
  if (!application || !mainActivity) {
    throw new Error("Could not find .MainActivity to add the Daseo assistant entry");
  }

  mainActivity["meta-data"] = upsertByName(mainActivity["meta-data"], {
    $: { "android:name": "android.app.shortcuts", "android:resource": `@xml/${SHORTCUTS_XML}` },
  });

  application["activity-alias"] = upsertByName(application["activity-alias"], {
    $: {
      "android:name": ALIAS_NAME,
      "android:targetActivity": ".MainActivity",
      "android:exported": "true",
    },
    "intent-filter": [
      {
        action: [{ $: { "android:name": "android.intent.action.ASSIST" } }],
        category: [{ $: { "android:name": "android.intent.category.DEFAULT" } }],
      },
    ],
  });

  // Daseo delta 69: the side-button session opens this invisible hop with the system's assistant
  // launch; it brings Daseo to the front and handles the lock screen (see the Kotlin template).
  application.activity = upsertByName(application.activity ?? [], {
    $: {
      "android:name": TRAMPOLINE_NAME,
      "android:exported": "false",
      "android:process": ASSISTANT_PROCESS,
      "android:theme": "@android:style/Theme.Translucent.NoTitleBar",
      "android:excludeFromRecents": "true",
      "android:noHistory": "true",
      "android:taskAffinity": "",
      "android:showWhenLocked": "true",
    },
  });

  let services = application.service ?? [];
  services = upsertByName(services, {
    $: {
      "android:name": ".DaseoVoiceInteractionService",
      "android:permission": "android.permission.BIND_VOICE_INTERACTION",
      "android:exported": "true",
      "android:process": ASSISTANT_PROCESS,
    },
    "meta-data": [
      {
        $: {
          "android:name": "android.voice_interaction",
          "android:resource": `@xml/${VOICE_INTERACTION_XML}`,
        },
      },
    ],
    "intent-filter": [
      { action: [{ $: { "android:name": "android.service.voice.VoiceInteractionService" } }] },
    ],
  });
  services = upsertByName(services, {
    $: {
      "android:name": ".DaseoVoiceInteractionSessionService",
      "android:permission": "android.permission.BIND_VOICE_INTERACTION",
      "android:exported": "true",
      "android:process": ASSISTANT_PROCESS,
    },
  });
  // Any app may bind a RecognitionService (AOSP defines no bind permission for it); this one
  // only answers ERROR_CLIENT and its metadata keeps it from becoming the system default.
  services = upsertByName(services, {
    $: {
      "android:name": ".DaseoRecognitionService",
      "android:exported": "true",
      "android:process": ASSISTANT_PROCESS,
    },
    "meta-data": [
      {
        $: {
          "android:name": "android.speech",
          "android:resource": `@xml/${RECOGNITION_SERVICE_XML}`,
        },
      },
    ],
    "intent-filter": [{ action: [{ $: { "android:name": "android.speech.RecognitionService" } }] }],
  });
  application.service = services;
  return manifest;
}

function patchMainActivity(contents) {
  if (contents.includes("DaseoQuickAsk.prepareLaunchIntent(")) return contents;
  if (!contents.includes(ACTIVITY_CREATE_LINE) || !contents.includes(ACTIVITY_COMPONENT_LINE)) {
    throw new Error("MainActivity does not have the shape the Daseo assistant entry patches");
  }
  let next = contents.replace(
    ACTIVITY_CREATE_LINE,
    [
      "    // Daseo delta 64: ASSIST becomes paseo://quick-ask before React Native reads the intent.",
      ACTIVITY_TRACK_LINE,
      ACTIVITY_PREPARE_LINE,
      ACTIVITY_CREATE_LINE,
      "    DaseoQuickAsk.dismissKeyguardIfLocked(this, intent)",
    ].join("\n"),
  );
  next = next.replace(
    ACTIVITY_COMPONENT_LINE,
    [
      "  override fun onNewIntent(intent: Intent) {",
      "    DaseoQuickAsk.prepareLaunchIntent(intent, DaseoQuickAsk.wasInForeground())",
      "    super.onNewIntent(intent)",
      "    DaseoQuickAsk.dismissKeyguardIfLocked(this, intent)",
      "  }",
      "",
      ACTIVITY_COMPONENT_LINE,
    ].join("\n"),
  );
  if (!/^import android\.content\.Intent$/m.test(next)) {
    next = next.replace(
      /^import android\.os\.Bundle$/m,
      "import android.content.Intent\nimport android.os.Bundle",
    );
  }
  if (!/^import android\.content\.Intent$/m.test(next)) {
    throw new Error("Could not add the Intent import to MainActivity");
  }
  return next;
}

function patchMainApplication(contents) {
  if (contents.includes(APPLICATION_GUARD_LINE)) return contents;
  if (!contents.includes(APPLICATION_CREATE_LINE)) {
    throw new Error(`Could not find "${APPLICATION_CREATE_LINE.trim()}" in MainApplication`);
  }
  return contents.replace(
    APPLICATION_CREATE_LINE,
    [
      APPLICATION_CREATE_LINE,
      "    // Daseo delta 64: the assistant services' process never loads React Native.",
      APPLICATION_GUARD_LINE,
    ].join("\n"),
  );
}

function writeAssistantSources(config) {
  return withDangerousMod(config, [
    "android",
    async (modConfig) => {
      const packageName = modConfig.android?.package;
      if (!packageName) throw new Error("Daseo assistant entry needs android.package");
      const mainRoot = path.join(modConfig.modRequest.platformProjectRoot, "app", "src", "main");
      const sourceDir = path.join(mainRoot, "java", ...packageName.split("."));
      fs.mkdirSync(sourceDir, { recursive: true });
      for (const template of KOTLIN_TEMPLATES) {
        const source = fs
          .readFileSync(path.join(TEMPLATE_DIR, template), "utf8")
          .replace("__PACKAGE__", packageName);
        fs.writeFileSync(path.join(sourceDir, template.replace(/\.template$/, "")), source);
      }
      const xmlDir = path.join(mainRoot, "res", "xml");
      fs.mkdirSync(xmlDir, { recursive: true });
      fs.writeFileSync(
        path.join(xmlDir, `${VOICE_INTERACTION_XML}.xml`),
        buildVoiceInteractionXml(packageName),
      );
      fs.writeFileSync(
        path.join(xmlDir, `${RECOGNITION_SERVICE_XML}.xml`),
        buildRecognitionServiceXml(),
      );
      fs.writeFileSync(path.join(xmlDir, `${SHORTCUTS_XML}.xml`), buildShortcutsXml(packageName));
      const koDir = path.join(mainRoot, "res", "values-ko");
      fs.mkdirSync(koDir, { recursive: true });
      fs.writeFileSync(
        path.join(koDir, "daseo_quick_ask.xml"),
        `<?xml version="1.0" encoding="utf-8"?>\n<resources>\n  <string name="daseo_quick_ask">${QUICK_ASK_LABELS["values-ko"]}</string>\n</resources>\n`,
      );
      return modConfig;
    },
  ]);
}

function withAndroidAssistantEntry(config) {
  let next = writeAssistantSources(config);
  next = withStringsXml(next, (modConfig) => {
    modConfig.modResults = AndroidConfig.Strings.setStringItem(
      [{ $: { name: "daseo_quick_ask" }, _: QUICK_ASK_LABELS.values }],
      modConfig.modResults,
    );
    return modConfig;
  });
  next = withAndroidManifest(next, (modConfig) => {
    addAssistantEntryToManifest(modConfig.modResults.manifest);
    return modConfig;
  });
  next = withMainActivity(next, (modConfig) => {
    if (modConfig.modResults.language !== "kt") {
      throw new Error("Daseo assistant entry expects a Kotlin MainActivity");
    }
    modConfig.modResults.contents = patchMainActivity(modConfig.modResults.contents);
    return modConfig;
  });
  return withMainApplication(next, (modConfig) => {
    if (modConfig.modResults.language !== "kt") {
      throw new Error("Daseo assistant entry expects a Kotlin MainApplication");
    }
    modConfig.modResults.contents = patchMainApplication(modConfig.modResults.contents);
    return modConfig;
  });
}

module.exports = withAndroidAssistantEntry;
module.exports.addAssistantEntryToManifest = addAssistantEntryToManifest;
module.exports.patchMainActivity = patchMainActivity;
module.exports.patchMainApplication = patchMainApplication;
module.exports.buildVoiceInteractionXml = buildVoiceInteractionXml;
module.exports.buildRecognitionServiceXml = buildRecognitionServiceXml;
module.exports.buildShortcutsXml = buildShortcutsXml;
